    function showPhoto(x){V.cancel($('#product-photo'));markPreview(false);$('#product-photo').dataset.photoType=presentation(x);$('#product-photo').innerHTML=x?`<img src="${esc(localAsset(x.src))}" alt="${esc(x.alt||m.name)}" data-presentation="${presentation(x)}" style="object-position:${position(x)}">`:placeholder();notePhoto(x);}
