    function updateURL(){const p=new URLSearchParams({id:m.id});if(activeColor)p.set('color',activeColor.id);if(activeFormat)p.set('format',activeFormat.id);history.replaceState(null,'',location.pathname+'?'+p);}
    function colorState(){$('#product-price-note').textContent=productPriceNote(m,activeColor);const priceDetails=productPriceDetails(m,activeColor);$('#product-price-details').textContent=priceDetails;$('#product-price-details').hidden=!priceDetails;const priceTable=$('.product-facts-table tbody');if(priceTable)priceTable.innerHTML=facts(withFormat(m,activeFormat),activeColor).map(([a,b])=>`<tr><th scope="row">${esc(a)}</th><td>${esc(b)}</td></tr>`).join('');const configure=$('#product-configure');if(configure)configure.href=configurationURL(m,activeColor);document.querySelectorAll('[data-color]').forEach(b=>{b.setAttribute('aria-pressed',b.dataset.color===activeColor?.id);const c=cs.find(c=>c.id===b.dataset.color);if(c)V.paintChip(b,m,c);});$('#selected-color-name').textContent=activeColor?.name||(m.colorStatus==='not_applicable'?(m.finish||'Sans option de couleur'):'À confirmer');$('#color-note').textContent=activeColor?`${activeColor.availabilityNote||'Teinte du fabricant; disponibilité à confirmer.'} ${V.smooth(m,activeColor)?'Le fini lisse reste lisse; la photo originale du profil est accessible à gauche.':activeColor.swatchTextureNote||''}`:m.colorStatus==='not_applicable'?'Le fini est défini par la référence; aucun nuancier de couleur ne s’applique.':'Le nuancier exact de cette référence reste à confirmer avec le fabricant.';showSelected();updateURL();}
    document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{activeColor=cs.find(c=>c.id===b.dataset.color);colorState();});colorState();
    $('#product-format')?.addEventListener('change',()=>{activeFormat=formats(m).find(f=>f.id===$('#product-format').value)||null;updateURL();const table=$('.product-facts-table tbody');if(table)table.innerHTML=facts(withFormat(m,activeFormat),activeColor).map(([a,b])=>`<tr><th scope="row">${esc(a)}</th><td>${esc(b)}</td></tr>`).join('');showSelected();});
    if($('#product-add'))$('#product-add').onclick=()=>{if(m.status==='pending_identity')return;if($('#product-format')&&!$('#product-format').reportValidity())return;const input=$('#product-quantity'),quantity=Number(input.value),unit=$('#product-unit').value;if(!input.reportValidity()||!Number.isFinite(quantity)||quantity<=0||quantity>1000000)return;const colorId=activeColor?.id||null,existing=list.items.find(x=>x.materialId===m.id&&x.colorId===colorId&&x.unit===unit&&(x.formatId||null)===(activeFormat?.id||null));if(existing){if(existing.quantity+quantity>1000000){notify('La quantité maximale est dépassée.');return;}existing.quantity=Math.round((existing.quantity+quantity)*1000)/1000;}else list.items.push({materialId:m.id,brand:m.brand,name:m.name,colorId,colorName:activeColor?.name||(m.colorStatus==='not_applicable'?(m.finish||'Sans option de couleur'):'À confirmer'),quantity,unit,formatId:activeFormat?.id||null,format:activeFormat?{...activeFormat}:null,formatName:activeFormat?formatLabel(activeFormat):null});if(persist())notify('Matériau ajouté à votre sélection.');};
    $('#product-docs').innerHTML=`<div><h2>La matière, en détail.</h2><table class="product-facts-table"><tbody>${facts(withFormat(m,activeFormat),activeColor).map(([a,b])=>`<tr><th scope="row">${esc(a)}</th><td>${esc(b)}</td></tr>`).join('')}</tbody></table><p class="product-source-note">Dimensions physiques et exposition utile sont distinctes. Les besoins saisis ne sont pas convertis automatiquement en boîtes ou en pièces livrables.</p>${m.gaps?.length?`<p class="product-source-note">${m.gaps.map(esc).join(' ')}</p>`:''}</div><div><h2>Les documents qui comptent.</h2>${(m.documents||[]).filter(d=>safe(d.url)).map(d=>`<a class="product-resource" href="${esc(safe(d.url))}" target="_blank" rel="noopener"><span>${esc(d.title)} <b>↗</b></span><small>${d.scope==='system'?'Document du système ou de la gamme. ':d.scope==='product'?'Document du produit. ':''}${esc(d.note||'Consultez les prescriptions et la version du fabricant.')}</small></a>`).join('')||'<p class="product-source-note">Les documents exacts de cette référence restent à compléter.</p>'}<div class="product-tech-buttons"><button id="product-pdf" class="mir-button">Préparer la fiche MIR ↓</button>${m.sourceUrl?`<a href="${esc(safe(m.sourceUrl))}" class="quiet-button" target="_blank" rel="noopener">Page fabricant ↗</a>`:''}</div><p class="product-source-note">La fiche MIR rassemble les renseignements référencés. Les documents originaux du fabricant demeurent la référence pour la pose et les garanties.</p></div>`;
