  async function productPDF(){const b=$('#product-pdf'),m=activeProduct,c=activeColor?{...activeColor}:null,f=activeFormat?{...activeFormat}:null;if(formats(m).length&&!f){$('#product-format').reportValidity();return;}b.disabled=true;b.textContent='Préparation…';try{const svg=await V.svg(withFormat(m,f),c);await window.MIRPDF.exportPlan({title:'MIR — Fiche matériau',subtitle:m.brand,filename:`MIR-${m.id}${f?'-'+f.id:''}.pdf`,faces:[{name:m.name,svg,summary:[...facts(withFormat(m,f),c).map(([a,v])=>`${a} : ${v}`),...(f?[`Format retenu : ${formatLabel(f)}`]:[]),`Couleur retenue : ${c?.name||(m.colorStatus==='not_applicable'?(m.finish||'Sans option de couleur'):'À confirmer')}`,surfaceTariff(m,c)?'Le prix du panneau sera calculé après saisie de la forme et des mesures. Disponibilité du fini et faisabilité MIR à confirmer.':productPriceNote(m,c)+'.','Les documents fabricant priment sur cette synthèse.',...(m.documents||[]).map(d=>`${d.title} — ${d.url}`),`Source produit : ${m.sourceUrl||'à confirmer'}`]}]});notify('Fiche PDF prête.');}catch(e){notify(e.message||'Impossible de préparer le PDF.');}finally{b.disabled=false;b.textContent='Préparer la fiche MIR ↓';}}
  function selectionHref(x){const p=new URLSearchParams({id:x.materialId});if(x.colorId)p.set('color',x.colorId);if(x.formatId)p.set('format',x.formatId);return 'produit.html?'+p;}
  function showSelection(){const project=$('#selection-project-name');project.value=list.project;project.oninput=()=>{list.project=project.value;persist();};function render(){updateCount();$('#selection-items').innerHTML=list.items.map((x,i)=>{const m=materials.find(m=>m.id===x.materialId);if(!sold(m))return `<article class="selection-item"><div><h2>${esc(x.name)}</h2><p>Article indisponible · exclu de l’export.</p></div><button class="remove-selection" data-remove="${i}" aria-label="Retirer ${esc(x.name)}">×</button></article>`;return `<article class="selection-item"><a href="${esc(selectionHref(x))}" class="selection-item-photo" data-selection-preview="${i}">${m?imageMarkup(m):placeholder()}</a><div><span class="shop-card-brand">${esc(x.brand)}</span><h2><a href="${esc(selectionHref(x))}">${esc(x.name)}</a></h2><p>Finition : ${esc(x.colorName)}${x.formatName?`<br>Format : ${esc(x.formatName)}`:''}<br>Prix et disponibilité à confirmer</p></div><label class="selection-qty"><span class="field-label">Quantité</span><input type="number" required min="0.01" max="1000000" step="any" value="${x.quantity}" data-qty="${i}" aria-label="Quantité pour ${esc(x.name)}"></label><label class="selection-unit"><span class="field-label">Unité du besoin</span><select data-unit="${i}" aria-label="Unité pour ${esc(x.name)}">${unitOptions(x.unit)}</select></label><button class="remove-selection" data-remove="${i}" aria-label="Retirer ${esc(x.name)}">×</button></article>`;}).join('')||'<div class="shop-empty"><p>Votre sélection est encore vide.</p><p><a href="boutique.html">Découvrir les matériaux →</a></p></div>';$('#selection-summary').innerHTML=`${list.items.length} référence${list.items.length>1?'s':''} dans votre projet.<small>Les quantités exprimées en pi², en pieds linéaires ou en pièces restent séparées. L’équipe MIR pourra préciser le conditionnement et les accessoires compatibles.</small>`;document.querySelectorAll('[data-selection-preview]').forEach(el=>{const x=list.items[+el.dataset.selectionPreview],m=materials.find(m=>m.id===x.materialId),c=m?.colors?.find(c=>c.id===x.colorId);if(m)V.render(el,withFormat(m,x.format),c);});$('#selection-export').disabled=!list.items.length;$('#selection-export-pdf').disabled=!list.items.some(x=>sold(materials.find(m=>m.id===x.materialId)));document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{list.items.splice(+b.dataset.remove,1);persist();render();});document.querySelectorAll('[data-qty]').forEach(input=>input.onchange=()=>{if(input.reportValidity()&&Number.isFinite(Number(input.value))&&Number(input.value)>0){list.items[+input.dataset.qty].quantity=Number(input.value);persist();}});document.querySelectorAll('[data-unit]').forEach(input=>input.onchange=()=>{list.items[+input.dataset.unit].unit=input.value;persist();});}
    const pdfButton=$('#selection-export-pdf'),pdfStatus=$('#selection-pdf-status');
    pdfButton.onclick=async()=>{
      if(!window.MIRPDF?.exportPlan||!window.MIRSelectionPDF?.buildOptions){
        pdfStatus.textContent='Export PDF indisponible. La sauvegarde JSON reste disponible.';
        return;
      }
      const available=list.items.filter(x=>sold(materials.find(m=>m.id===x.materialId)));
      pdfButton.disabled=true;pdfButton.setAttribute('aria-busy','true');
      pdfStatus.textContent='Préparation du PDF de votre sélection…';
      try{
        const options=window.MIRSelectionPDF.buildOptions({
          project:list.project,items:available,excludedCount:list.items.length-available.length
        });
        const result=await window.MIRPDF.exportPlan(options);
        pdfStatus.textContent='PDF prêt ('+result.pages+' page'+(result.pages>1?'s':'')+'). Utilisez le bouton Télécharger dans le panneau.';
      }catch(error){
        pdfStatus.textContent='PDF non préparé : '+String(error?.message||'Erreur inconnue')+'. Sauvegardez votre JSON si nécessaire.';
      }finally{
        pdfButton.removeAttribute('aria-busy');
        pdfButton.disabled=!list.items.some(x=>sold(materials.find(m=>m.id===x.materialId)));
      }
    };
    $('#selection-export').onclick=()=>{const payload={...list,createdAt:new Date().toISOString(),status:'selection_non_commandee',note:'Quantités souhaitées; prix, stock, unités livrables et compatibilités à confirmer.',items:list.items.filter(x=>sold(materials.find(m=>m.id===x.materialId))).map(x=>({...x,sourceUrl:materials.find(m=>m.id===x.materialId)?.sourceUrl||null}))};const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.href=url;a.download='MIR-selection-materiaux.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);};render();
  }
  document.addEventListener('click',event=>{const b=event.target.closest('[data-card-color]');if(!b)return;const m=materials.find(m=>m.id===b.dataset.material),c=m?.colors?.find(c=>c.id===b.dataset.cardColor),card=b.closest('[data-shop-card]');if(!m||!c||!card)return;card.querySelectorAll('[data-card-color]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));V.render(card.querySelector('.card-preview'),m,c);card.querySelector('.card-photo-label').textContent='Couleur choisie';card.querySelector('.card-color-name').textContent=c.name;card.querySelectorAll('[data-card-link]').forEach(a=>a.href=`produit.html?id=${encodeURIComponent(m.id)}&color=${encodeURIComponent(c.id)}`);});
  async function init(){updateCount();const [response,visibility]=await Promise.all([fetch('./catalogue-fd6866b49d21.json'),fetch('./boutique-visibilite.json',{cache:'no-cache'})]);if(!visibility.ok)throw new Error('La disponibilité des articles ne peut pas être vérifiée. Réessayez dans un instant.');const {hidden}=await visibility.json();if(!Array.isArray(hidden))throw new Error('La disponibilité des articles est invalide.');hiddenProducts=new Set(hidden);if(!response.ok)throw new Error('Le catalogue ne peut pas être chargé. Réessayez dans un instant.');materials=(await response.json()).materials||[];const view=document.body.dataset.commerceView;if(view==='shop')showShop();if(view==='product')showProduct();if(view==='selection')showSelection();}
  window.addEventListener('storage',e=>{if(e.key===KEY){try{const s=JSON.parse(e.newValue);if(s&&Array.isArray(s.items)){list=s;updateCount();if(document.body.dataset.commerceView==='selection')showSelection();}}catch{}}});
  init().catch(e=>{const target=$('#shop-grid')||$('#product-detail')||$('#selection-items');if(target)target.innerHTML=`<p class="shop-empty">${esc(e.message)}</p>`;});
